<script src="https://cdnjs.cloudflare.com/ajax/libs/marked/12.0.2/marked.min.js"></script>
<script src="https://cdnjs.cloudflare.com/ajax/libs/dompurify/3.1.6/purify.min.js"></script>
<script id="data" type="application/json">__DATA__</script>
<script>
const byId=Object.fromEntries(D.tasks.map(t=>[t.id,t]));
const PHASES=['First','Then','Next'];const PH={First:0,Then:1,Next:2};const PR=p=>p?+p.slice(1):9;
const LABEL={done:'Done',partial:'Partly done',notdone:'Not done',manual:'Review yourself',unknown:"Couldn't check"};
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
function status(t){const c=t.checks;if(!c.length)return 'manual';const r=c.filter(x=>x.result!=='Skipped');if(!r.length)return 'unknown';const f=r.filter(x=>x.result==='Failed').length;if(!f)return 'done';return f===r.length?'notdone':'partial'}
D.tasks.forEach(t=>{t.st=status(t);t.fails=t.checks.filter(c=>c.result==='Failed');t.passes=t.checks.filter(c=>c.result==='Passed')});
const checkable=D.tasks.filter(t=>t.st!=='manual');
const count=s=>D.tasks.filter(t=>t.st===s).length;
const blockers=t=>(t.dependencies||[]).map(d=>byId[d]).filter(d=>d&&d.st!=='done');
const pct=(n,d)=>d?n/d*100:0;
const bar=ts=>{const n=ts.length;return `<div class="bar"><span style="width:${pct(ts.filter(t=>t.st==='done').length,n)}%;background:var(--done)"></span><span style="width:${pct(ts.filter(t=>t.st==='partial').length,n)}%;background:var(--part)"></span><span style="width:${pct(ts.filter(t=>t.st==='notdone').length,n)}%;background:var(--fail)"></span></div>`};
document.getElementById('pillarnav').innerHTML=`<a class="on" href="#">Identity <small>${D.tasks.length}</small></a>`+D.otherPillars.map(p=>`<a class="off" href="#" title="Same view in the full build">${p.name} <small>${p.tasks}</small></a>`).join('');
document.getElementById('tiles').innerHTML=['done','partial','notdone','unknown','manual'].map(s=>`<span><i class="dot d-${s}"></i><b>${count(s)}</b>${LABEL[s].toLowerCase()}</span>`).join('');
const phases=PHASES.map(p=>{const ts=checkable.filter(t=>t.phase===p);return{p,ts,done:ts.filter(t=>t.st==='done').length,manual:D.tasks.filter(t=>t.phase===p&&t.st==='manual').length}});
const cur=phases.find(x=>x.done<x.ts.length)||phases[2];
const next=checkable.filter(t=>t.st==='notdone'||t.st==='partial').sort((a,b)=>(PH[a.phase]-PH[b.phase])||(blockers(a).length-blockers(b).length)||(PR(a.priority)-PR(b.priority))||(b.fails.length-a.fails.length)).slice(0,5);
const areaName=id=>D.areas.find(a=>a.id===id)?.name;
document.getElementById('where').innerHTML=`<div><h2>Where you are</h2><p class="lede" style="margin:0">You're in the <b>${cur.p}</b> phase: ${cur.done} of the ${cur.ts.length} ${cur.p} tasks that Maester checks are done. The workshop finishes the First tasks before it starts the Then tasks.</p>
<div class="phases">${phases.map(x=>`<div class="phase ${x===cur?'cur':''}"><div class="n">${x.p}${x===cur?' · you are here':''}</div><b style="font-variant-numeric:tabular-nums">${x.done} of ${x.ts.length}</b>${bar(x.ts)}<div class="n" style="margin-top:4px">+${x.manual} to review yourself</div></div>`).join('')}</div></div>
<div><div class="sec">Do these next</div><ol class="next">${next.map((t,i)=>{const b=blockers(t);return `<li><button type="button" data-id="${t.id}"><span class="num">${i+1}</span><span><span>${esc(t.name)}</span><div class="why">${esc(areaName(t.functionalAreaId))} › ${esc(t.swimlane)} · ${t.fails.length} of ${t.checks.length} checks fail${b.length?` · after ${b.map(x=>esc(x.name)).join(', ')
document.querySelectorAll('ol.next button').forEach(b=>b.onclick=()=>select(b.dataset.id,true));
const areas=D.areas.map(a=>{const ts=D.tasks.filter(t=>t.functionalAreaId===a.id);const lanes=[];ts.forEach(t=>{const n=t.swimlane||a.name;let l=lanes.find(x=>x.name===n);if(!l)lanes.push(l={name:n,tasks:[]});l.tasks.push(t)});return{...a,tasks:ts,lanes}});
let curArea=areas[0].id,selected=null;
function drawAreas(){document.getElementById('areas').innerHTML=areas.map(a=>{const ck=a.tasks.filter(t=>t.st!=='manual');const gaps=ck.filter(t=>t.st==='notdone'||t.st==='partial').length;return `<button type="button" class="area" aria-pressed="${a.id===curArea}" data-a="${esc(a.id)}"><span class="t">${icon(a.icon,'lg')}${esc(a.name)}</span><span class="why">${ck.filter(t=>t.st==='done').length} 
 document.querySelectorAll('.area').forEach(b=>b.onclick=()=>{curArea=b.dataset.a;drawAreas();drawBoard()})}
function drawBoard(){const a=areas.find(x=>x.id===curArea);const hide=document.getElementById('hidedone').checked,only=document.getElementById('onlychecked').checked;
 document.getElementById('areatitle').textContent=a.name;
 const keep=t=>!(hide&&t.st==='done')&&!(only&&t.st==='manual');
 let h=`<div class="ph">Swimlane</div>`+PHASES.map(p=>{const ts=a.tasks.filter(t=>t.phase===p&&t.st!=='manual');return `<div class="ph"><b>${p}</b>${ts.length?`${ts.filter(t=>t.st==='done').length} of ${ts.length} done`:''}</div>`}).join('');
 a.lanes.forEach(l=>{const ck=l.tasks.filter(t=>t.st!=='manual');h+=`<div class="lane"><div class="t">${esc(l.name)}</div><div class="why">${ck.length?`${ck.filter(t=>t.st==='done').length} of ${ck.length} done`:'Nothing Maester checks'}${l.tasks.length-ck.length?` · ${l.tasks.length-ck.length} to review`:''}</div></div>`;
  PHASES.forEach(p=>{const ts=l.tasks.filter(t=>t.phase===p&&keep(t));h+=`<div class="cell ${ts.length?'':'none'}"><span class="phl">${p}</span>${ts.map(card).join('')}</div>`})});
 document.getElementById('board').innerHTML=h;
 document.querySelectorAll('.task').forEach(b=>b.onclick=()=>select(b.dataset.id))}
function card(t){const b=blockers(t);const sub=t.st==='manual'?'Review yourself':t.st==='unknown'?"Couldn't check":`${t.passes.length} of ${t.checks.length} checks pass`;
 return `<button type="button" class="task ${t.st==='manual'?'manual':''} ${selected===t.id?'sel':''}" data-id="${t.id}">${icon(t.icon,'',t.st)}<span class="nm">${esc(t.name)}${t.origin==='maester'?' <span class="pill mae">Maester</span>':''}</span><span class="sub">${sub}${t.priority?` · ${t.priority}`:''}${b.length?` · after ${esc(b[0].name)}${b.length>1?` +${b.length-1}`:''}`:''}</span></butt
function icon(f,cls,st){const u=D.icons[f];return `<span class="ico ${cls||''}">${u?`<img src="${u}" alt="">`:''}${st?`<i class="dot d-${st}"></i>`:''}</span>`}
const SRC={microsoft:'Zero Trust mapping',maester:'Maester mapping'};
function cleanDoc(md){return md.replace(/^---[\s\S]*?---\s*/,'').replace(/<iframe[\s\S]*?<\/iframe>/g,'').replace(/^#\s+.*\n/,'').replace(/\*\*Implementation Effort:\*\*.*\n|\*\*User Impact:\*\*.*\n/g,'')}
function select(id,jump){const t=byId[id];selected=id;if(t.functionalAreaId!==curArea){curArea=t.functionalAreaId;drawAreas()}drawBoard();
 const deps=(t.dependencies||[]).map(d=>byId[d]).filter(Boolean);const after=D.tasks.filter(x=>(x.dependencies||[]).includes(id));
 const html=DOMPurify.sanitize(marked.parse(cleanDoc(t.doc||'')));const ord=['Failed','Skipped','Passed'];
 document.getElementById('detail').innerHTML=`<div class="eyebrow">${esc(areaName(t.functionalAreaId))} › ${esc(t.swimlane)}</div><div style="display:flex;gap:10px;align-items:center">${icon(t.icon,'lg')}<h3>${esc(t.name)}</h3></div>
 <div class="status"><i class="dot d-${t.st}"></i>${LABEL[t.st]}${t.checks.length?`<span style="font-weight:400;color:var(--muted)"> · ${t.passes.length} of ${t.checks.length} checks pass</span>`:''}</div>
 <div class="meta"><span class="pill">${t.phase}</span>${t.priority?`<span class="pill">${t.priority}</span>`:''}<span class="pill">Effort ${esc(t.implementationEffort)}</span><span class="pill">User impact ${esc(t.userImpact)}</span>${t.license?`<span class="pill">${esc(t.license)}</span>`:''}${t.CISAMaturityStage?`<span class="pill">CISA ${esc(t.CISAMaturityStage)}</span>`:''}${t.origin==='maest
 ${t.note?`<div class="note">${esc(t.note)}</div>`:''}
 ${deps.length?`<div class="sec">Do first</div>${deps.map(d=>`<div><i class="dot d-${d.st}"></i> <a href="#" data-go="${d.id}">${esc(d.name)}</a> <span class="empty">${LABEL[d.st]}</span></div>`).join('')}`:''}
 <div class="sec">Checks</div>${t.checks.length?`<div class="checks">${[...t.checks].sort((a,b)=>ord.indexOf(a.result)-ord.indexOf(b.result)).map(c=>`<div class="chk"><span class="pill ${c.result==='Failed'?'fail':c.result==='Passed'?'pass':'skip'}">${c.result}</span><span><span class="id">${esc(c.id)}</span> ${esc(c.title)}<div class="src">${c.source==='same-check'?`Same check as ${esc(c.via)}`:S
 ${after.length?`<div class="sec">Comes before</div>${after.map(d=>`<div><a href="#" data-go="${d.id}">${esc(d.name)}</a></div>`).join('')}`:''}
 <div class="sec">Workshop guidance</div><div class="doc">${html||'<p class="empty">No guidance page.</p>'}</div>
 ${t.link?`<p><a href="${esc(t.link)}" target="_blank" rel="noopener">Open this task in the Zero Trust Workshop</a></p>`:''}`;
 document.querySelectorAll('#detail [data-go]').forEach(a=>a.onclick=e=>{e.preventDefault();select(a.dataset.go,true)});
 if(jump){const el=innerWidth<1180?document.getElementById('detail'):document.querySelector('.task.sel');el&&el.scrollIntoView({behavior:'smooth',block:innerWidth<1180?'start':'center'})}
}
document.getElementById('hidedone').onchange=drawBoard;document.getElementById('onlychecked').onchange=drawBoard;
curArea=next[0].functionalAreaId;drawAreas();select(next[0].id);
</script>

