 const ic=u?`<image href="${u}" x="11" y="11" width="22" height="22"/>`:`<rect x="15" y="15" width="14" height="14" rx="3" fill="none" stroke="#a3a3a3" stroke-width="1.5"/>`;
 const badge=t.st==='manual'?`<circle cx="40" cy="40" r="6.5" fill="#fff" stroke="#a3a3a3" stroke-width="1.5" stroke-dasharray="2.4 2"/>`:`<circle cx="40" cy="40" r="7" fill="${BADGE[t.st]}" stroke="#fff" stroke-width="2"/><g transform="translate(40 40)">${GLYPH[t.st]}</g>`;
