 a.tasks.forEach(t=>(t.dependencies||[]).forEach(d=>{const p=byId[d];if(p&&p.functionalAreaId===a.id)els.push({group:'edges',data:{id:'e-'+d+'-'+t.id,source:d,target:t.id},classes:'dep '+edgeClass(p)})}));
