// Dev server only: the Zero Trust plan the pack would attach, built from the pack's own files the way
// packs/zero-trust-assessment/helpers/Get-MtZtaWorkshopPlan.ps1 builds it at run time, so the view can be worked
// on without a run. Never part of a built report.

import type { Workshop, WorkshopCheckRef, WorkshopTask } from "@/lib/zeroTrust"

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Raw = Record<string, any>

const files = import.meta.glob<Raw>("../../../packs/zero-trust-assessment/workshop/*.json", { import: "default" })
const taxonomyFile = import.meta.glob<Raw>("../../../packs/zero-trust-assessment/taxonomy.json", { import: "default" })

const ORDER = ["identity", "devices", "data", "network", "infrastructure", "security-operations", "ai"]

export async function sampleWorkshop(): Promise<Workshop> {
  const loaded: Record<string, Raw> = {}
  for (const [path, load] of Object.entries(files)) loaded[path.split("/").pop()!.replace(/\.json$/, "")] = await load()
  const taxonomy = (await Object.values(taxonomyFile)[0]?.())?.Tests || {}
  const overlay = loaded.maester || { Tasks: {}, ExtraTasks: [] }
  const icons: Record<string, string> = loaded.icons?.Icons || {}
  const used: Record<string, string> = {}
  const useIcon = (n?: string) => { if (n && icons[n]) used[n] = icons[n] }
  const pillars = ORDER.filter((id) => loaded[id]).map((id) => {
    const p = loaded[id]
    const tasks: WorkshopTask[] = (p.Tasks || []).map((t: Raw) => {
      const checks: WorkshopCheckRef[] = []
      for (const z of t.Checks || []) {
        checks.push({ Id: z, Source: "microsoft" })
        for (const m of taxonomy[String(z).replace(/^ZTA\./, "")]?.AlsoCheckedBy || []) checks.push({ Id: m, Source: "same-check", Via: z })
      }
      const extra = overlay.Tasks?.[t.Id]
      for (const m of extra?.Tests || []) checks.push({ Id: m, Source: "maester" })
      useIcon(t.Icon)
      return { ...t, Note: extra?.Note, Origin: "workshop", Checks: checks.filter((c, i) => checks.findIndex((x) => x.Id === c.Id) === i) }
    })
    for (const x of (overlay.ExtraTasks || []).filter((x: Raw) => x.Pillar === id)) {
      tasks.push({ ...x, Origin: "maester", Checks: (x.Tests || []).map((m: string) => ({ Id: m, Source: "maester" })) })
    }
    for (const a of p.Areas || []) useIcon(a.Icon)
    return { Id: p.Id, Name: p.Name, Areas: p.Areas || [], Tasks: tasks }
  })
  const updated = Object.values(loaded).find((f) => f?.Source?.Updated)?.Source?.Updated
  return { Schema: "maester.zero-trust-workshop/1", Source: { Name: "Microsoft Zero Trust Workshop", Url: "https://zerotrust.microsoft.com", Updated: updated }, Pillars: pillars, Icons: used }
}

// Where each box of one functional area's diagram goes: the area's swimlanes are rows, the workshop's three phases
// are columns (bands), each task is a box in its lane and phase, and an arrow runs from each task to the tasks
// that wait on it. A dependency on a task in another area is a small "From …" or "Leads to …" box at the lane's
// left, which opens that task. Plain geometry, drawn by ZeroTrustDiagram.

import { PHASES, dependentsOf, type Area, type Plan, type Task } from "@/lib/zeroTrust"

export const NODE_W = 210
const GAP_X = 22, GAP_Y = 14, BAND_PAD = 18, HEAD_W = 200, LANE_PAD = 14, LANE_GAP = 16, BAND_TOP = 44

export interface LaidTask { kind: "task"; task: Task; x: number; y: number; w: number; h: number }
export interface LaidGhost { kind: "ghost"; id: string; task: Task; dir: "in" | "out"; label: string; x: number; y: number; w: number; h: number }
export interface LaidLane { key: string; name: string; tasks: Task[]; x: number; y: number; w: number; h: number }
export interface LaidBand { phase: string; x: number; w: number }
export interface LaidEdge { id: string; from: string; to: string; path: string; tone: "ok" | "wait" | "rev" }
export interface Layout { width: number; height: number; bands: LaidBand[]; lanes: LaidLane[]; nodes: (LaidTask | LaidGhost)[]; edges: LaidEdge[] }

const lines = (s: string, max: number) => {
  let n = 1, len = 0
  for (const w of s.split(/\s+/)) {
    if (len && len + 1 + w.length > max) { n++; len = w.length } else len += (len ? 1 : 0) + w.length
  }
  return n
}
const taskH = (name: string) => Math.max(58, lines(name, 22) * 16 + 24)
const ghostH = (label: string, name: string) => (lines(label, 26) + lines(name, 26)) * 15 + 16

// Within a phase, a task comes right after the task it waits on, so chains read left to right.
function chainOrder(ts: Task[]) {
  const ids = new Set(ts.map((t) => t.id))
  const byId = new Map(ts.map((t) => [t.id, t]))
  const out: Task[] = [], seen = new Set<string>()
  const sorted = [...ts].sort((a, b) => a.index - b.index)
  const visit = (t: Task) => {
    if (seen.has(t.id)) return
    for (const d of t.dependencies) if (ids.has(d)) visit(byId.get(d)!)
    if (seen.has(t.id)) return
    seen.add(t.id); out.push(t)
    for (const n of sorted) if (n.dependencies.includes(t.id)) visit(n)
  }
  sorted.forEach(visit)
  return out
}

const tone = (t: Task): LaidEdge["tone"] => (t.st === "done" ? "ok" : t.st === "manual" || t.st === "unknown" ? "rev" : "wait")

// An elbow from the right edge of one box to the left edge of the other, or around when the target is not to the right.
function elbow(a: { x: number; y: number; w: number; h: number }, b: { x: number; y: number; w: number; h: number }) {
  const x1 = a.x + a.w, y1 = a.y + a.h / 2, x2 = b.x, y2 = b.y + b.h / 2
  if (x2 - x1 >= 16) {
    const mx = Math.round(x1 + Math.min(18, (x2 - x1) / 2))
    return `M${x1} ${y1}H${mx}V${y2}H${x2 - 1}`
  }
  // Same column: leave the bottom of the first box and enter the top of the second.
  const ax = a.x + a.w / 2, bx = b.x + b.w / 2
  if (b.y > a.y + a.h) return `M${ax} ${a.y + a.h}V${Math.round((a.y + a.h + b.y) / 2)}H${bx}V${b.y - 1}`
  return `M${x1} ${y1}H${x1 + 12}V${Math.min(a.y, b.y) - 8}H${x2 - 12}V${y2}H${x2 - 1}`
}

export function layoutArea(plan: Plan, area: Area): Layout {
  const areaName = (t: Task) => plan.pillars.find((p) => p.id === t.pillarId)?.areas.find((a) => a.id === t.areaId)?.name || ""
  const most = PHASES.map((p) => Math.max(0, ...area.lanes.map((l) => l.tasks.filter((t) => t.phase === p).length)))
  const cols = most.map((m) => (m <= 3 ? Math.max(m, 1) : m <= 9 ? 3 : 4))
  const bandW = cols.map((c) => c * NODE_W + (c - 1) * GAP_X + BAND_PAD * 2)
  const bandX: number[] = []
  let x = HEAD_W
  PHASES.forEach((_, i) => { bandX[i] = x; x += bandW[i] + 10 })
  const right = x - 10
  const bands: LaidBand[] = PHASES.map((p, i) => ({ phase: p, x: bandX[i], w: bandW[i] }))
  const nodes: (LaidTask | LaidGhost)[] = []
  const lanes: LaidLane[] = []
  const edges: LaidEdge[] = []
  const at = new Map<string, LaidTask | LaidGhost>()
  let y = BAND_TOP
  for (const lane of area.lanes) {
    const top = y, inner = top + LANE_PAD
    let laneH = 0
    PHASES.forEach((p, pi) => {
      const ts = chainOrder(lane.tasks.filter((t) => t.phase === p))
      let ry = 0, rowH = 0
      ts.forEach((t, i) => {
        const c = i % cols[pi]
        if (c === 0 && i) { ry += rowH + GAP_Y; rowH = 0 }
        const h = taskH(t.name)
        rowH = Math.max(rowH, h)
        const node: LaidTask = { kind: "task", task: t, x: bandX[pi] + BAND_PAD + c * (NODE_W + GAP_X), y: inner + ry, w: NODE_W, h }
        nodes.push(node); at.set(t.id, node)
      })
      laneH = Math.max(laneH, ts.length ? ry + rowH : 0)
    })
    // Dependencies on tasks of other areas, as small boxes under the lane's name.
    let gy = inner + 46
    const ghosts: LaidGhost[] = []
    for (const t of lane.tasks) {
      for (const d of t.dependencies) {
        const p = plan.byId.get(d)
        if (p && p.areaId !== area.id) {
          const label = `From ${areaName(p)}`
          const g: LaidGhost = { kind: "ghost", id: `in:${p.id}:${t.id}`, task: p, dir: "in", label, x: 14, y: gy, w: HEAD_W - 34, h: ghostH(label, p.name) }
          ghosts.push(g); gy += g.h + 8
          edges.push({ id: g.id, from: g.id, to: t.id, path: "", tone: tone(p) })
        }
      }
      for (const n of dependentsOf(plan, t)) {
        if (n.areaId !== area.id) {
          const label = `Leads to ${areaName(n)}`
          const g: LaidGhost = { kind: "ghost", id: `out:${t.id}:${n.id}`, task: n, dir: "out", label, x: 14, y: gy, w: HEAD_W - 34, h: ghostH(label, n.name) }
          ghosts.push(g); gy += g.h + 8
          edges.push({ id: g.id, from: t.id, to: g.id, path: "", tone: tone(t) })
        }
      }
    }
    for (const g of ghosts) { nodes.push(g); at.set(g.id, g) }
    laneH = Math.max(laneH, 40, gy - inner - 8)
    lanes.push({ key: lane.key, name: lane.name, tasks: lane.tasks, x: 0, y: top, w: right + 8, h: laneH + LANE_PAD * 2 })
    y = top + laneH + LANE_PAD * 2 + LANE_GAP
  }
  for (const t of area.tasks) {
    for (const d of t.dependencies) {
      const p = plan.byId.get(d)
      if (p && p.areaId === area.id) edges.push({ id: `${d}>${t.id}`, from: d, to: t.id, path: "", tone: tone(p) })
    }
  }
  for (const e of edges) {
    const a = at.get(e.from), b = at.get(e.to)
    if (a && b) e.path = elbow(a, b)
  }
  return { width: right + 16, height: y - LANE_GAP + 12, bands, lanes, nodes, edges: edges.filter((e) => e.path) }
}

/** The tasks before and after a task, as far as the chain goes inside the area, with the task itself. */
export function chainOf(plan: Plan, id: string) {
  const out = new Set<string>([id])
  const up = (tid: string) => { for (const d of plan.byId.get(tid)?.dependencies || []) if (!out.has(d)) { out.add(d); up(d) } }
  const down = (tid: string) => {
    const t = plan.byId.get(tid)
    if (!t) return
    for (const n of dependentsOf(plan, t)) if (!out.has(n.id)) { out.add(n.id); down(n.id) }
  }
  up(id); down(id)
  return out
}

// One functional area of the Zero Trust plan as a diagram: swimlanes as rows, the workshop's phases as bands,
// tasks as boxes coloured by status and arrows for what must come first. Drag to move; Ctrl or ⌘ with the wheel
// (or a pinch) zooms; a sideways scroll pans. An ordinary scroll moves the page, so the page never gets stuck
// under the diagram.

import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react"
import { STATUS_LABEL, type Area, type Plan, type Task } from "@/lib/zeroTrust"
import { chainOf, layoutArea, type LaidGhost, type LaidTask } from "@/lib/zeroTrustLayout"
import { Icon } from "./ui"

interface View { x: number; y: number; k: number }
const MIN_K = 0.3, MAX_K = 1.6
const clampK = (k: number) => Math.min(MAX_K, Math.max(MIN_K, k))

export function ZeroTrustDiagram({ plan, area, current, selected, focus, faded, cover, onSelect }: {
  plan: Plan
  area: Area
  /** The phase the reader is in, marked on its band. */
  current: string
  selected: string | null
  /** A task to bring into view when it changes (a pick from the table, the list or a link). */
  focus: { id: string; n: number } | null
  /** Tasks the filters leave out, drawn faint. */
  faded: (t: Task) => boolean
  /** How many pixels on the right a panel covers, so a task is never centred behind it. */
  cover: number
  onSelect: (id: string) => void
}) {
  const layout = useMemo(() => layoutArea(plan, area), [plan, area])
  const stage = useRef<HTMLDivElement>(null)
  const [view, setView] = useState<View>({ x: 0, y: 0, k: 1 })
  const viewRef = useRef(view)
  viewRef.current = view
  const [hover, setHover] = useState<string | null>(null)
  const drag = useRef<{ x: number; y: number; vx: number; vy: number; moved: boolean; id: number } | null>(null)
  const suppressClick = useRef(false)

  const fit = () => {
    const el = stage.current
    if (!el) return
    const k = clampK(Math.min(1, (el.clientWidth - 24) / layout.width))
    setView({ x: Math.max(12, (el.clientWidth - layout.width * k) / 2), y: 12, k })
  }
  // A new area starts fitted to the width, top first.
  useLayoutEffect(fit, [layout])

  const zoomAt = (k: number, cx: number, cy: number) => setView((v) => {
    const nk = clampK(k)
    return { k: nk, x: cx - ((cx - v.x) / v.k) * nk, y: cy - ((cy - v.y) / v.k) * nk }
  })
  const zoomBy = (f: number) => { const el = stage.current; if (el) zoomAt(viewRef.current.k * f, el.clientWidth / 2, el.clientHeight / 2) }

  // The wheel: only zoom (Ctrl/⌘ or pinch) and sideways scrolls belong to the diagram.
  useEffect(() => {
    const el = stage.current
    if (!el) return
    const onWheel = (e: WheelEvent) => {
      const r = el.getBoundingClientRect()
      if (e.ctrlKey || e.metaKey) {
        e.preventDefault()
        const step = e.deltaMode ? 0.05 : 0.002
        zoomAt(viewRef.current.k * Math.exp(-e.deltaY * step), e.clientX - r.left, e.clientY - r.top)
      } else if (Math.abs(e.deltaX) > Math.abs(e.deltaY)) {
        e.preventDefault()
        setView((v) => ({ ...v, x: v.x - e.deltaX }))
      }
    }
    el.addEventListener("wheel", onWheel, { passive: false })
    return () => el.removeEventListener("wheel", onWheel)
  }, [])

  // Bring the focused task into the part of the stage no panel covers.
  useEffect(() => {
    if (!focus) return
    const el = stage.current
    const node = layout.nodes.find((n): n is LaidTask => n.kind === "task" && n.task.id === focus.id)
    if (!el || !node) return
    const visW = Math.max(160, el.clientWidth - cover)
    const v = viewRef.current
    const k = Math.max(v.k, 0.8)
    const left = v.x + node.x * v.k, rightEdge = left + node.w * v.k, top = v.y + node.y * v.k, bottom = top + node.h * v.k
    if (k === v.k && left >= 8 && rightEdge <= visW - 8 && top >= 8 && bottom <= el.clientHeight - 8) return
    setView({ k, x: visW / 2 - (node.x + node.w / 2) * k, y: el.clientHeight / 2 - (node.y + node.h / 2) * k })
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [focus, layout])

  const lit = useMemo(() => {
    const id = hover || selected
    if (!id || !layout.nodes.some((n) => n.kind === "task" && n.task.id === id)) return null
    const chain = chainOf(plan, id)
    return chain.size > 1 ? chain : null
  }, [hover, selected, layout, plan])

  const onPointerDown = (e: React.PointerEvent) => {
    if (e.button !== 0) return
    drag.current = { x: e.clientX, y: e.clientY, vx: viewRef.current.x, vy: viewRef.current.y, moved: false, id: e.pointerId }
  }
  const onPointerMove = (e: React.PointerEvent) => {
    const d = drag.current
    if (!d || d.id !== e.pointerId) return
    const dx = e.clientX - d.x, dy = e.clientY - d.y
    if (!d.moved && Math.hypot(dx, dy) < 4) return
    if (!d.moved) { d.moved = true; stage.current?.setPointerCapture(e.pointerId) }
    setView((v) => ({ ...v, x: d.vx + dx, y: d.vy + dy }))
  }
  const onPointerUp = (e: React.PointerEvent) => {
    const d = drag.current
    if (d?.moved) suppressClick.current = true
    drag.current = null
    if (stage.current?.hasPointerCapture(e.pointerId)) stage.current.releasePointerCapture(e.pointerId)
  }

  const content = useMemo(() => {
    const dimmed = (id: string) => !!lit && !lit.has(id)
    const box = (n: LaidTask) => {
      const t = n.task
      const ran = t.ran.length
      return (
        <button key={t.id} type="button" data-id={t.id}
          className={`mt-zt-node s-${t.st}${t.id === selected ? " sel" : ""}${faded(t) ? " faded" : ""}${dimmed(t.id) ? " dim" : ""}`}
          style={{ left: n.x, top: n.y, width: n.w, minHeight: n.h }}
          onMouseEnter={() => setHover(t.id)} onMouseLeave={() => setHover(null)}
          aria-label={`${t.name}: ${STATUS_LABEL[t.st]}`} aria-pressed={t.id === selected}
          onClick={() => onSelect(t.id)}>
          <TaskIcon plan={plan} task={t} />
          <span className="nm">{t.name}</span>
          <span className="sub">{t.priority ? <b>{t.priority}</b> : null}{t.checks.length ? `${t.passes.length}/${ran || t.checks.length} checks` : "Review yourself"}</span>
        </button>
      )
    }
    const ghost = (n: LaidGhost) => (
      <button key={n.id} type="button" className={`mt-zt-ghost s-${n.task.st}${dimmed(n.task.id) ? " dim" : ""}`} style={{ left: n.x, top: n.y, width: n.w, minHeight: n.h }}
        title={`Open ${n.task.name}`} onClick={() => onSelect(n.task.id)}>
        <span className="k">{n.label}</span><span className="nm"><i className={`mt-zt-dot s-${n.task.st}`} />{n.task.name}</span>
      </button>
    )
    return (
      <>
        {layout.bands.map((b) => {
          const ts = area.tasks.filter((t) => t.phase === b.phase && t.st !== "manual")
          return (
            <div key={b.phase} className={`mt-zt-band${b.phase === current ? " cur" : ""}`} style={{ left: b.x, width: b.w, height: layout.height }}>
              <b>{b.phase}{b.phase === current ? " · you are here" : ""}</b>
              <span>{ts.length ? `${ts.filter((t) => t.st === "done").length} of ${ts.length} checked done` : "Nothing checked"}</span>
            </div>
          )
        })}
        {layout.lanes.map((l) => {
          const ck = l.tasks.filter((t) => t.st !== "manual")
          return (
            <div key={l.key} className="mt-zt-lane" style={{ left: l.x, top: l.y, width: l.w, height: l.h }}>
              <b>{l.name}</b>
              <span>{ck.length ? `${ck.filter((t) => t.st === "done").length} of ${ck.length} done` : "Nothing Maester checks"}{l.tasks.length - ck.length ? ` · ${l.tasks.length - ck.length} to review` : ""}</span>
            </div>
          )
        })}
        <svg className="mt-zt-edges" width={layout.width} height={layout.height} aria-hidden="true">
          <defs>
            {["ok", "wait", "rev"].map((k) => <marker key={k} id={`mt-zt-arrow-${k}`} viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" className={`mt-zt-ah ${k}`} /></marker>)}
          </defs>
          {layout.edges.map((e) => {
            const on = !!lit && lit.has(e.from.replace(/^(in|out):/, "").split(":")[0]) && lit.has(e.to.replace(/^(in|out):[^:]*:/, ""))
            return <path key={e.id} d={e.path} className={`mt-zt-edge ${e.tone}${lit ? (on ? " hl" : " dim") : ""}`} markerEnd={`url(#mt-zt-arrow-${e.tone})`} />
          })}
        </svg>
        {layout.nodes.map((n) => (n.kind === "task" ? box(n) : ghost(n)))}
      </>
    )
  }, [layout, area, current, selected, lit, faded, plan, onSelect])

  return (
    <div className="mt-zt-diagram">
      <div ref={stage} className="mt-zt-stage" onPointerDown={onPointerDown} onPointerMove={onPointerMove} onPointerUp={onPointerUp} onPointerCancel={onPointerUp}
        onClickCapture={(e) => { if (suppressClick.current) { e.stopPropagation(); e.preventDefault(); suppressClick.current = false } }}>
        <div className="mt-zt-canvas" style={{ width: layout.width, height: layout.height, transform: `translate(${view.x}px, ${view.y}px) scale(${view.k})` }}>{content}</div>
        <div className="mt-zt-tools" role="toolbar" aria-label="Diagram controls">
          <button type="button" onClick={() => zoomBy(0.8)} aria-label="Zoom out" title="Zoom out">−</button>
          <span className="mt-num" aria-live="polite">{Math.round(view.k * 100)}%</span>
          <button type="button" onClick={() => zoomBy(1.25)} aria-label="Zoom in" title="Zoom in">+</button>
          <button type="button" onClick={fit} aria-label="Fit to width" title="Fit to width"><Icon name="maximize" /></button>
        </div>
      </div>
    </div>
  )
}

export function TaskIcon({ plan, task, size = "" }: { plan: Plan; task: Task; size?: "" | "lg" }) {
  const src = plan.icon(task.icon)
  return (
    <span className={`mt-zt-ico ${size}`} aria-hidden="true">
      {src ? <img src={src} alt="" /> : <i />}
      <i className={`mt-zt-badge s-${task.st}`} />
    </span>
  )
}

// The Zero Trust plan: Microsoft's Zero Trust Workshop for one pillar, with what this run found for each task.
// A summary and the tasks to do next, then every task as a table (grouped by functional area and swimlane) or,
// one area at a time, as a diagram of what must come first. A task opens in a panel on the right that leaves the
// table or diagram in view. The plan comes from the Zero Trust Assessment pack (see lib/zeroTrust.ts).

import { useCallback, useEffect, useMemo, useRef, useState, type ReactNode } from "react"
import { Markdown } from "@/components/Markdown"
import { Link, useLocation, useNavigate } from "@/lib/router"
import {
  LEVEL, PHASES, PHASE_RANK, STATUSES, STATUS_LABEL, STATUS_RANK, blockersOf, buildPlan, cleanDoc, dependentsOf, loadWorkshop, orderedChecks,
  priorityRank, workshopAttachment, type Check, type Pillar, type Plan, type Task, type TaskStatus, type Workshop,
} from "@/lib/zeroTrust"
import { useReport } from "@/components/report/ReportContext"
import { Footer } from "@/components/report/lists"
import { Icon, Pill, plural } from "@/components/report/ui"
import { TaskIcon, ZeroTrustDiagram } from "@/components/report/ZeroTrustDiagram"

type Filters = { status: Set<string>; phase: Set<string>; priority: Set<string>; effort: Set<string> }
const FILTERS: { key: keyof Filters; label: string; options: [string, string][]; get: (t: Task) => string }[] = [
  { key: "status", label: "Status", options: STATUSES.map((s) => [s, STATUS_LABEL[s]]), get: (t) => t.st },
  { key: "phase", label: "Phase", options: PHASES.map((p) => [p, p]), get: (t) => t.phase },
  { key: "priority", label: "Priority", options: [["P0", "P0"], ["P1", "P1"], ["P2", "P2"], ["P3", "P3"], ["none", "No priority"]], get: (t) => t.priority || "none" },
  { key: "effort", label: "Effort", options: [["Low", "Low"], ["Medium", "Medium"], ["High", "High"], ["none", "Not set"]], get: (t) => t.effort || "none" },
]
const emptyFilters = (): Filters => ({ status: new Set(), phase: new Set(), priority: new Set(), effort: new Set() })

const COLUMNS: { key: string; label: string; sm?: boolean; value: (t: Task) => string | number }[] = [
  { key: "task", label: "Task", value: (t) => t.name.toLowerCase() },
  { key: "status", label: "Status", value: (t) => STATUS_RANK[t.st] },
  { key: "phase", label: "Phase", sm: true, value: (t) => PHASE_RANK[t.phase] },
  { key: "priority", label: "Priority", sm: true, value: (t) => priorityRank(t.priority ?? undefined) },
  { key: "checks", label: "Checks", value: (t) => (t.ran.length ? t.passes.length / t.ran.length : t.checks.length ? -0.5 : -1) },
  { key: "effort", label: "Effort", sm: true, value: (t) => LEVEL[t.effort || ""] || 9 },
  { key: "impact", label: "User impact", sm: true, value: (t) => LEVEL[t.userImpact || ""] || 9 },
  { key: "licence", label: "Licence", sm: true, value: (t) => t.license || "~" },
]

const SOURCE: Record<string, string> = { microsoft: "Zero Trust mapping", maester: "Maester mapping" }
const isOpenTask = (t: Task) => t.st === "notdone" || t.st === "partial"

function StatusBadge({ st }: { st: TaskStatus }) {
  return <span className={`mt-zt-st s-${st}`}><i className={`mt-zt-dot s-${st}`} />{STATUS_LABEL[st]}</span>
}

function Rollup({ tasks }: { tasks: Task[] }) {
  const n = tasks.length || 1
  const c = (s: TaskStatus) => tasks.filter((t) => t.st === s).length
  return (
    <span className="mt-zt-roll" role="img" aria-label={`${c("done")} done, ${c("partial")} partly done, ${c("notdone")} not done, ${c("unknown") + c("manual")} to review`}>
      {(["done", "partial", "notdone", "unknown"] as TaskStatus[]).map((s) => c(s) ? <i key={s} className={`s-${s}`} style={{ width: `${(c(s) / n) * 100}%` }} /> : null)}
    </span>
  )
}

function rollText(tasks: Task[]) {
  const ck = tasks.filter((t) => t.st !== "manual")
  const fix = tasks.filter(isOpenTask).length
  const review = tasks.filter((t) => t.st === "manual" || t.st === "unknown").length
  return `${ck.length ? `${ck.filter((t) => t.st === "done").length} of ${ck.length} done` : "Nothing Maester checks"}${fix ? ` · ${fix} to fix` : ""}${review ? ` · ${review} to review` : ""}`
}

function CheckBar({ task }: { task: Task }) {
  if (!task.checks.length) return <span className="mt-muted">No checks</span>
  const p = task.passes.length, f = task.fails.length, other = task.checks.length - p - f
  return (
    <span className="mt-zt-checks" title={`${p} passed, ${f} failed, ${other} did not run`}>
      <span className="b" aria-hidden="true">{p ? <i className="p" style={{ flex: p }} /> : null}{f ? <i className="f" style={{ flex: f }} /> : null}{other ? <i className="o" style={{ flex: other }} /> : null}</span>
      <span className="mt-num">{p}/{task.checks.length}</span>
    </span>
  )
}

const Level = ({ value }: { value: string | null }) => (value ? <span className="mt-zt-level"><b aria-hidden="true">{[1, 2, 3].map((i) => <i key={i} className={i <= (LEVEL[value] || 0) ? "on" : ""} />)}</b>{value}</span> : <span className="mt-muted">–</span>)
const Priority = ({ value }: { value: string | null }) => (value ? <span className={`mt-zt-prio ${value.toLowerCase()}`}>{value}</span> : <span className="mt-muted">–</span>)

function FilterMenu({ def, value, onChange }: { def: (typeof FILTERS)[number]; value: Set<string>; onChange: (next: Set<string>) => void }) {
  const [open, setOpen] = useState(false)
  const ref = useRef<HTMLDivElement>(null)
  useEffect(() => {
    if (!open) return
    const onDoc = (e: MouseEvent) => { if (!ref.current?.contains(e.target as Node)) setOpen(false) }
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") { e.stopPropagation(); setOpen(false) } }
    document.addEventListener("mousedown", onDoc)
    window.addEventListener("keydown", onKey, true)
    return () => { document.removeEventListener("mousedown", onDoc); window.removeEventListener("keydown", onKey, true) }
  }, [open])
  const names = def.options.filter(([v]) => value.has(v)).map(([, l]) => l)
  return (
    <div className="mt-zt-fm" ref={ref}>
      <button type="button" className={`mt-btn${value.size ? " on" : ""}`} aria-expanded={open} onClick={() => setOpen((o) => !o)}>
        {def.label}{names.length ? <b>: {names.length > 2 ? `${names.length} selected` : names.join(", ")}</b> : null}<Icon name="chevron" />
      </button>
      {open && (
        <div className="mt-zt-fmenu" role="group" aria-label={def.label}>
          {def.options.map(([v, l]) => (
            <label key={v}><input type="checkbox" checked={value.has(v)} onChange={() => { const next = new Set(value); if (next.has(v)) next.delete(v); else next.add(v); onChange(next) }} />
              {def.key === "status" ? <i className={`mt-zt-dot s-${v}`} /> : null}{l}</label>
          ))}
          {value.size ? <button type="button" className="mt-link" onClick={() => onChange(new Set())}>Clear</button> : null}
        </div>
      )}
    </div>
  )
}

function Tiles({ pillar }: { pillar: Pillar }) {
  const ts = pillar.tasks
  const checkable = ts.filter((t) => t.st !== "manual")
  const done = checkable.filter((t) => t.st === "done")
  const fix = ts.filter(isOpenTask)
  const review = ts.filter((t) => t.st === "manual" || t.st === "unknown")
  const ran = ts.flatMap((t) => t.ran)
  const pass = ts.flatMap((t) => t.passes)
  const byPhase = (list: Task[], of?: Task[]) => PHASES.map((p) => ({ p, v: list.filter((t) => t.phase === p).length, max: of ? of.filter((t) => t.phase === p).length : 0 }))
  const spark = (vals: { p: string; v: number; max: number }[], cls: string) => {
    const top = Math.max(1, ...vals.map((x) => x.max || x.v))
    return <span className="mt-zt-spark" aria-hidden="true">{vals.map((x) => <span key={x.p} title={`${x.p}: ${x.max ? `${x.v} of ${x.max}` : x.v}`}><b><i className={cls} style={{ height: `${((x.v / (x.max || top)) || 0) * 100}%` }} /></b>{x.p[0]}</span>)}</span>
  }
  const tile = (label: ReactNode, value: ReactNode, sub: string, sp: ReactNode) => <div className="mt-zt-tile"><div className="k">{label}</div><div className="v">{value}</div>{sp}<div className="s">{sub}</div></div>
  return (
    <div className="mt-zt-tiles">
      {tile(<><i className="mt-zt-dot s-done" />Tasks done</>, <>{done.length}<small> of {checkable.length}</small></>, "Tasks Maester checks, with every check passing", spark(byPhase(done, checkable), "s-done"))}
      {tile(<><i className="mt-zt-dot s-notdone" />To fix</>, fix.length, `${ts.filter((t) => t.st === "notdone").length} not done · ${ts.filter((t) => t.st === "partial").length} partly done`, spark(byPhase(fix), "s-notdone"))}
      {tile(<><i className="mt-zt-dot s-info" />Checks passing</>, ran.length ? `${Math.round((pass.length / ran.length) * 100)}%` : "–", `${pass.length} of ${ran.length} checks that ran`, spark(PHASES.map((p) => ({ p, v: ts.filter((t) => t.phase === p).flatMap((t) => t.passes).length, max: ts.filter((t) => t.phase === p).flatMap((t) => t.ran).length })), "s-info"))}
      {tile(<><i className="mt-zt-dot s-manual" />Review yourself</>, review.length, `${ts.filter((t) => t.st === "manual").length} with no check · ${ts.filter((t) => t.st === "unknown").length} couldn't check`, spark(byPhase(review), "s-manual"))}
    </div>
  )
}

function TaskPanel({ plan, task, view, onGo, onSwap, onClose }: { plan: Plan; task: Task; view: "table" | "diagram"; onGo: (id: string) => void; onSwap: () => void; onClose: () => void }) {
  const { openTest, openId } = useReport()
  const closeRef = useRef<HTMLButtonElement>(null)
  const panel = useRef<HTMLElement>(null)
  const pillar = plan.pillars.find((p) => p.id === task.pillarId)
  const area = pillar?.areas.find((a) => a.id === task.areaId)
  const deps = task.dependencies.map((d) => plan.byId.get(d)).filter((d): d is Task => !!d)
  const after = dependentsOf(plan, task)
  const checks = orderedChecks(task)
  const doc = cleanDoc(task.doc)
  useEffect(() => { panel.current?.scrollTo(0, 0) }, [task.id])
  useEffect(() => { closeRef.current?.focus({ preventScroll: true }) }, [])
  useEffect(() => {
    // Escape closes the test sheet first when one is open over the panel.
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape" && !openId && !e.defaultPrevented) onClose() }
    window.addEventListener("keydown", onKey)
    return () => window.removeEventListener("keydown", onKey)
  }, [onClose, openId])
  const taskLink = (d: Task, extra?: ReactNode) => (
    <button key={d.id} type="button" className="mt-zt-tlink" onClick={() => onGo(d.id)}>
      <i className={`mt-zt-dot s-${d.st}`} /><span className="nm">{d.name}</span>
      <span className="mt-muted">{extra ?? STATUS_LABEL[d.st]}{d.areaId !== task.areaId ? ` · ${pillar?.areas.find((a) => a.id === d.areaId)?.name || ""}` : ""}</span>
    </button>
  )
  const checkRow = (c: Check) => {
    const via = c.Source === "same-check" ? `Same check as ${c.Via}` : SOURCE[c.Source || ""] || ""
    const body = <>
      {c.row ? <Pill result={c.result} /> : <span className="mt-badge">Not in this run</span>}
      <span><span className="mt-mono id">{c.Id}</span> {c.title !== c.Id ? c.title : ""}<span className="src">{via}</span></span>
    </>
    return c.row
      ? <button key={c.Id} type="button" className="mt-zt-check" onClick={() => openTest(c.Id, checks.filter((x) => x.row).map((x) => x.Id))}>{body}</button>
      : <div key={c.Id} className="mt-zt-check">{body}</div>
  }
  return (
    <aside ref={panel} className="mt-zt-fly" role="dialog" aria-labelledby="mt-zt-fly-title">
      <button ref={closeRef} type="button" className="mt-btn icon mt-zt-x" onClick={onClose} aria-label="Close" title="Close (Esc)"><Icon name="close" /></button>
      <div className="mt-zt-flyhead">
        <div className="mt-eyebrow">{area?.name}{task.swimlane ? ` › ${task.swimlane}` : ""}</div>
        <div className="t"><TaskIcon plan={plan} task={task} size="lg" /><h2 id="mt-zt-fly-title">{task.name}</h2></div>
        <div className="mt-zt-statusline"><StatusBadge st={task.st} />{task.checks.length ? <span className="mt-muted">{task.passes.length} of {task.ran.length || task.checks.length} checks pass</span> : <span className="mt-muted">No check measures this task. Review it yourself.</span>}</div>
        <div className="mt-zt-meta">
          <span className="mt-chip">{task.phase}</span>
          {task.priority && <span className="mt-chip">{task.priority}</span>}
          {task.effort && <span className="mt-chip">Effort {task.effort}</span>}
          {task.userImpact && <span className="mt-chip">User impact {task.userImpact}</span>}
          {task.license && <span className="mt-chip">{task.license}</span>}
          {task.cisa && <span className="mt-chip">CISA {task.cisa}</span>}
          {task.origin === "maester" && <span className="mt-chip ember">Added by Maester</span>}
        </div>
        <button type="button" className="mt-btn" onClick={onSwap}><Icon name={view === "table" ? "feature" : "framework"} />{view === "table" ? "Show in the diagram" : "Show in the table"}</button>
      </div>
      <div className="mt-zt-flybody">
        {task.note && <div className="mt-callout"><span>{task.note}</span></div>}
        {deps.length > 0 && <section><h3>Do first</h3><div className="mt-zt-tlist">{deps.map((d) => taskLink(d))}</div></section>}
        <section>
          <h3>Checks</h3>
          {checks.length ? <div className="mt-zt-checklist">{checks.map(checkRow)}</div> : <p className="mt-note">No Maester or Zero Trust Assessment check measures this task.</p>}
        </section>
        {after.length > 0 && <section><h3>Comes before</h3><div className="mt-zt-tlist">{after.map((d) => taskLink(d))}</div></section>}
        <section>
          <h3>Workshop guidance</h3>
          {doc ? <Markdown className="mt-prose mt-zt-doc">{doc}</Markdown> : <p className="mt-note">The workshop has no guidance page for this task.</p>}
        </section>
      </div>
    </aside>
  )
}

export default function ZeroTrustPage() {
  const { model } = useReport()
  const { pathname } = useLocation()
  const navigate = useNavigate()
  const attachment = workshopAttachment(model)
  const [workshop, setWorkshop] = useState<Workshop | null>(null)
  const [error, setError] = useState("")
  useEffect(() => {
    setWorkshop(null); setError("")
    if (attachment) loadWorkshop(attachment).then(setWorkshop, (e) => setError(String(e?.message || e)))
  }, [attachment])
  const plan = useMemo(() => (workshop ? buildPlan(workshop, model) : null), [workshop, model])

  if (!attachment) return <div className="mt-wrap"><h1 className="mt-h1">Zero Trust plan</h1><p className="mt-lead">This run has no Zero Trust plan. Run the Zero Trust Assessment pack (<code>Invoke-Maester -Pack ZTA</code>) to add it.</p></div>
  if (error) return <div className="mt-wrap"><h1 className="mt-h1">Zero Trust plan</h1><div className="mt-callout warn"><span>{error}</span></div></div>
  if (!plan) return <div className="mt-wrap"><h1 className="mt-h1">Zero Trust plan</h1><p className="mt-note">Opening the plan…</p></div>
  const [, , pillarId = "", mode = ""] = pathname.split("/")
  const pillar = plan.pillars.find((p) => p.id === pillarId) || plan.pillars.find((p) => p.checksInRun) || plan.pillars[0]
  if (!pillar) return <div className="mt-wrap"><h1 className="mt-h1">Zero Trust plan</h1><p className="mt-lead">The plan has no pillars.</p></div>
  return <PillarView key={pillar.id} plan={plan} pillar={pillar} view={mode === "diagram" ? "diagram" : "table"}
    setView={(v, replace) => navigate(`/zero-trust/${pillar.id}${v === "diagram" ? "/diagram" : ""}`, replace ? { replace: true } : undefined)} />
}

function PillarView({ plan, pillar, view, setView }: { plan: Plan; pillar: Pillar; view: "table" | "diagram"; setView: (v: "table" | "diagram", replace?: boolean) => void }) {
  const [q, setQ] = useState("")
  const [filters, setFilters] = useState<Filters>(emptyFilters)
  const [checkedOnly, setCheckedOnly] = useState(false)
  const [sort, setSort] = useState<{ key: string | null; dir: 1 | -1 }>({ key: null, dir: 1 })
  const [collapsed, setCollapsed] = useState<Set<string>>(() => new Set())
  const [selected, setSelected] = useState<string | null>(null)
  const [area, setArea] = useState(pillar.areas[0]?.id || "")
  const [focus, setFocus] = useState<{ id: string; n: number } | null>(null)
  const [wide, setWide] = useState(() => window.innerWidth)
  useEffect(() => { const on = () => setWide(window.innerWidth); window.addEventListener("resize", on); return () => window.removeEventListener("resize", on) }, [])

  const task = selected ? plan.byId.get(selected) || null : null
  const areaName = (id: string) => pillar.areas.find((a) => a.id === id)?.name || ""
  const match = useCallback((t: Task) => {
    if (checkedOnly && !t.checks.length) return false
    for (const f of FILTERS) { const s = filters[f.key]; if (s.size && !s.has(f.get(t))) return false }
    if (q) {
      const hay = [t.name, t.id, t.swimlane, areaName(t.areaId), ...t.checks.flatMap((c) => [c.Id, c.title])].join(" ").toLowerCase()
      if (!q.toLowerCase().split(/\s+/).every((w) => hay.includes(w))) return false
    }
    return true
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [q, filters, checkedOnly, pillar])
  const anyFilter = !!q || checkedOnly || FILTERS.some((f) => filters[f.key].size)
  const clear = () => { setQ(""); setFilters(emptyFilters()); setCheckedOnly(false) }
  const faded = useCallback((t: Task) => !match(t), [match])

  // Opening a task from anywhere: the table opens its rows, the diagram switches to its area; both bring it into view.
  const open = (id: string, from?: "list" | "link") => {
    const t = plan.byId.get(id)
    if (!t) return
    if (t.pillarId !== pillar.id) return
    setSelected(id)
    if (view === "diagram") { if (t.areaId !== area) setArea(t.areaId); setFocus({ id, n: Date.now() }) }
    else {
      if (!match(t)) clear()
      setCollapsed((c) => { const n = new Set(c); n.delete(`a:${t.areaId}`); n.delete(`l:${t.laneKey}`); return n })
      if (from) requestAnimationFrame(() => document.getElementById(`mt-zt-row-${t.id}`)?.scrollIntoView({ block: "center", behavior: "smooth" }))
    }
  }
  const swap = () => {
    if (view === "table") { if (task) { setArea(task.areaId); setFocus({ id: task.id, n: Date.now() }) } setView("diagram") }
    else { setView("table"); if (task) requestAnimationFrame(() => document.getElementById(`mt-zt-row-${task.id}`)?.scrollIntoView({ block: "center" })) }
  }
  const close = useCallback(() => setSelected(null), [])
  // The panel covers the right of the page; a diagram task is never centred behind it.
  const cover = task && wide > 760 ? Math.min(560, wide) - Math.max(0, wide - (document.getElementById("report-main")?.getBoundingClientRect().right || wide)) - 40 : 0

  const sortTasks = (ts: Task[]) => {
    if (!sort.key) return ts
    const col = COLUMNS.find((c) => c.key === sort.key)!
    return [...ts].sort((a, b) => { const x = col.value(a), y = col.value(b); return (x < y ? -1 : x > y ? 1 : 0) * sort.dir || a.index - b.index })
  }
  const toggle = (k: string) => setCollapsed((c) => { const n = new Set(c); if (n.has(k)) n.delete(k); else n.add(k); return n })
  const others = plan.pillars.filter((p) => p.tasks.length)
  const shown = pillar.tasks.filter(match).length

  return (
    <div className="mt-wrap wide mt-zt">
      <div className="mt-head">
        <div className="mt-eyebrow">Zero Trust · {plan.source?.Name || "Microsoft Zero Trust Workshop"}</div>
        <h1 className="mt-h1">{pillar.name}</h1>
        <p className="mt-lead">The workshop's {pillar.name} plan with what this run found. Every task is listed, grouped by functional area and swimlane, in the workshop's three phases: First, Then and Next. A task is done when every check that measures it passed; tasks no check measures are yours to review.</p>
      </div>
      {others.length > 1 && (
        <div className="mt-seg mt-zt-pillars" role="group" aria-label="Pillar">
          {others.map((p) => <Link key={p.id} to={`/zero-trust/${p.id}${view === "diagram" ? "/diagram" : ""}`} aria-current={p.id === pillar.id ? "page" : undefined} className={p.id === pillar.id ? "on" : ""}>{p.name}<span className="mt-muted"> {p.tasks.length}</span></Link>)}
        </div>
      )}
      {!pillar.checksInRun && <div className="mt-callout"><span>None of the checks that measure the {pillar.name} tasks ran, so every task shows as one to review. Run the Zero Trust Assessment for this pillar, or Maester's own tests, to measure them.</span></div>}
      <Tiles pillar={pillar} />

      {pillar.next.length > 0 && (
        <section className="mt-sec">
          <div className="mt-sechead"><h2 className="mt-h2">Do these next</h2><span className="mt-note">You're in the {pillar.current} phase: {pillar.tasks.filter((t) => t.phase === pillar.current && t.st === "done").length} of {pillar.tasks.filter((t) => t.phase === pillar.current && t.st !== "manual").length} checked {pillar.current} tasks done.</span></div>
          <ol className="mt-zt-next">
            {pillar.next.map((t, i) => {
              const b = blockersOf(plan, t)
              return (
                <li key={t.id}><button type="button" aria-pressed={selected === t.id} onClick={() => open(t.id, "list")}>
                  <span className="n">{i + 1}</span>
                  <span className="nm">{t.name}</span>
                  <span className="why"><StatusBadge st={t.st} /><span className="mt-chip">{t.phase}</span>{t.priority && <Priority value={t.priority} />}<span>{t.fails.length} of {t.ran.length} checks fail</span></span>
                  <span className="mt-muted sub">{areaName(t.areaId)} › {t.swimlane}{b.length ? ` · after ${b.map((x) => x.name).join(", ")}` : ""}</span>
                </button></li>
              )
            })}
          </ol>
        </section>
      )}

      <section className="mt-sec">
        <div className="mt-zt-toolbar">
          <div className="mt-seg" role="group" aria-label="View">
            <button type="button" aria-pressed={view === "table"} onClick={() => view !== "table" && swap()}><Icon name="framework" />Table</button>
            <button type="button" aria-pressed={view === "diagram"} onClick={() => view !== "diagram" && swap()}><Icon name="feature" />Diagram</button>
          </div>
          <input className="mt-input" type="search" placeholder="Search tasks, swimlanes or check IDs" aria-label="Search tasks" value={q} onInput={(e) => setQ((e.target as HTMLInputElement).value)} />
          {FILTERS.map((f) => <FilterMenu key={f.key} def={f} value={filters[f.key]} onChange={(next) => setFilters((x) => ({ ...x, [f.key]: next }))} />)}
          <label className="mt-zt-tog"><input type="checkbox" checked={checkedOnly} onChange={(e) => setCheckedOnly((e.target as HTMLInputElement).checked)} />Only tasks Maester checks</label>
          {view === "table" && <button type="button" className="mt-btn" onClick={() => setCollapsed((c) => (c.size ? new Set() : new Set(pillar.areas.map((a) => `a:${a.id}`))))}>{collapsed.size ? "Expand all" : "Collapse all"}</button>}
        </div>
        <p className="mt-note">{anyFilter ? <>{view === "diagram" ? "Tasks that don't match are faded. " : ""}Showing {shown} of {plural(pillar.tasks.length, "task")}. <button type="button" className="mt-link mt-zt-linkbtn" onClick={clear}>Clear filters</button></> : view === "diagram" ? "Drag to move · Ctrl or ⌘ and scroll, or pinch, to zoom · Arrows point from a task to the tasks that wait on it." : `${plural(pillar.tasks.length, "task")} in ${plural(pillar.areas.length, "functional area")}. Select a task to see its checks and the workshop's guidance.`}</p>

        {view === "table" ? (
          <div className="mt-zt-grid">
            <table className="mt-table">
              <thead><tr>{COLUMNS.map((c) => (
                <th key={c.key} className={c.sm ? "mt-hide-sm" : undefined} aria-sort={sort.key === c.key ? (sort.dir > 0 ? "ascending" : "descending") : "none"}>
                  <button type="button" onClick={() => setSort((s) => (s.key !== c.key ? { key: c.key, dir: 1 } : s.dir > 0 ? { key: c.key, dir: -1 } : { key: null, dir: 1 }))}>{c.label}<span className="mt-zt-sort" aria-hidden="true">{sort.key === c.key ? (sort.dir > 0 ? "↑" : "↓") : "↕"}</span></button>
                </th>))}</tr></thead>
              <tbody>
                {pillar.areas.map((a) => {
                  const ts = a.tasks.filter(match)
                  if (!ts.length) return null
                  const ak = `a:${a.id}`, aOpen = !collapsed.has(ak)
                  return [
                    <tr key={ak} className="grp mt-zt-area" onClick={() => toggle(ak)}>
                      <td colSpan={2}><span className="mt-zt-gcell"><button type="button" className="mt-zt-chev" aria-expanded={aOpen} aria-label={`${aOpen ? "Collapse" : "Expand"} ${a.name}`} onClick={(e) => { e.stopPropagation(); toggle(ak) }}><Icon name="chevron" /></button>
                        {plan.icon(a.icon) ? <img className="mt-zt-aico" src={plan.icon(a.icon)!} alt="" /> : null}<b>{a.name}</b><span className="mt-muted">{ts.length}</span></span></td>
                      <td colSpan={6}><span className="mt-zt-gcell"><Rollup tasks={a.tasks} /><span className="mt-muted mt-hide-sm">{rollText(a.tasks)}</span>
                        <button type="button" className="mt-link mt-zt-linkbtn" onClick={(e) => { e.stopPropagation(); setArea(a.id); setView("diagram") }}>Diagram</button></span></td>
                    </tr>,
                    ...(aOpen ? a.lanes.flatMap((l) => {
                      const lt = l.tasks.filter(match)
                      if (!lt.length) return []
                      const lk = `l:${l.key}`, lOpen = !collapsed.has(lk)
                      return [
                        <tr key={lk} className="mt-zt-lanerow" onClick={() => toggle(lk)}>
                          <td colSpan={2}><span className="mt-zt-gcell"><button type="button" className="mt-zt-chev" aria-expanded={lOpen} aria-label={`${lOpen ? "Collapse" : "Expand"} ${l.name}`} onClick={(e) => { e.stopPropagation(); toggle(lk) }}><Icon name="chevron" /></button><b>{l.name}</b><span className="mt-muted">{lt.length}</span></span></td>
                          <td colSpan={6}><span className="mt-zt-gcell"><Rollup tasks={l.tasks} /><span className="mt-muted mt-hide-sm">{rollText(l.tasks)}</span></span></td>
                        </tr>,
                        ...(lOpen ? sortTasks(lt).map((t) => (
                          <tr key={t.id} id={`mt-zt-row-${t.id}`} className={`click mt-zt-task${selected === t.id ? " on" : ""}${t.st === "manual" ? " manual" : ""}`} onClick={() => (selected === t.id ? close() : open(t.id))}>
                            <td className="ttl"><span className="mt-zt-tcell"><TaskIcon plan={plan} task={t} /><button type="button" className="mt-zt-tname" aria-expanded={selected === t.id} onClick={(e) => { e.stopPropagation(); if (selected === t.id) close(); else open(t.id) }}>{t.name}</button>{t.origin === "maester" && <span className="mt-chip ember">Maester</span>}</span></td>
                            <td><StatusBadge st={t.st} /></td>
                            <td className="mt-hide-sm">{t.phase}</td>
                            <td className="mt-hide-sm"><Priority value={t.priority} /></td>
                            <td><CheckBar task={t} /></td>
                            <td className="mt-hide-sm"><Level value={t.effort} /></td>
                            <td className="mt-hide-sm"><Level value={t.userImpact} /></td>
                            <td className="mt-hide-sm mt-zt-lic">{t.license || <span className="mt-muted">–</span>}</td>
                          </tr>
                        )) : []),
                      ]
                    }) : []),
                  ]
                })}
                {!shown && <tr><td colSpan={8} className="mt-empty">No task matches. <button type="button" className="mt-link mt-zt-linkbtn" onClick={clear}>Clear filters</button></td></tr>}
              </tbody>
            </table>
          </div>
        ) : (
          <>
            <div className="mt-zt-areas" role="group" aria-label="Functional area">
              {pillar.areas.map((a) => {
                const ck = a.tasks.filter((t) => t.st !== "manual")
                const gaps = a.tasks.filter(isOpenTask).length
                return (
                  <button key={a.id} type="button" className="mt-zt-acard" aria-pressed={a.id === area} onClick={() => setArea(a.id)}>
                    <span className="t">{plan.icon(a.icon) ? <img className="mt-zt-aico" src={plan.icon(a.icon)!} alt="" /> : null}{a.name}</span>
                    <span className="mt-muted">{ck.filter((t) => t.st === "done").length} of {ck.length} checked done{gaps ? ` · ${gaps} to fix` : ""}</span>
                    <Rollup tasks={ck} />
                  </button>
                )
              })}
            </div>
            {pillar.areas.find((a) => a.id === area) && (
              <ZeroTrustDiagram plan={plan} area={pillar.areas.find((a) => a.id === area)!} current={pillar.current} selected={selected} focus={focus}
                faded={faded} cover={cover} onSelect={(id) => (id === selected ? close() : open(id))} />
            )}
          </>
        )}
      </section>
      {plan.source?.Url && <p className="mt-note">The plan is Microsoft's <a className="mt-link" href={plan.source.Url} target="_blank" rel="noopener noreferrer">Zero Trust Workshop</a>{plan.source.Updated ? `, as of ${plan.source.Updated}` : ""}. Maester adds its own tests to the tasks they measure, and a few tasks the workshop does not have.</p>}
      <Footer />
      {task && <TaskPanel plan={plan} task={task} view={view} onGo={(id) => open(id, "link")} onSwap={swap} onClose={close} />}
    </div>
  )
}

