/* Zero Trust plan (pages/report/ZeroTrustPage.tsx, components/report/ZeroTrustDiagram.tsx). Task status colours:
   done green, partly done amber, not done red, couldn't check grey, review yourself a dashed ring. */
.mt-zt { --zt-done: var(--mt-pass); --zt-partial: var(--mt-warn); --zt-notdone: var(--mt-fail); --zt-unknown: var(--mt-skip); --zt-band: var(--mt-canvas); --zt-band-cur: var(--mt-info-bg); }
.mt-zt-dot { width: 8px; height: 8px; border-radius: 99px; display: inline-block; flex: none; background: var(--mt-skip); }
.mt-zt-dot.s-done { background: var(--zt-done); } .mt-zt-dot.s-partial { background: var(--zt-partial); } .mt-zt-dot.s-notdone { background: var(--zt-notdone); }
.mt-zt-dot.s-unknown { background: var(--zt-unknown); } .mt-zt-dot.s-manual { background: transparent; box-shadow: inset 0 0 0 1.5px var(--mt-ink-3); } .mt-zt-dot.s-info { background: var(--mt-info); }
.mt-zt-st { display: inline-flex; align-items: center; gap: 6px; font-size: 12.5px; white-space: nowrap; color: var(--mt-ink-2); }
.mt-zt-pillars a { padding: 5px 10px; border-radius: 7px; font-size: 12.5px; color: var(--mt-ink-2); }
.mt-zt-pillars a.on { background: var(--mt-paper); color: var(--mt-ink); font-weight: 600; box-shadow: 0 1px 2px rgba(0, 0, 0, .08); }

.mt-zt-tiles { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 220px), 1fr)); gap: 10px; }
.mt-zt-tile { border: 1px solid var(--mt-line); border-radius: 12px; padding: 12px 14px; display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "k sp" "v sp" "s s"; gap: 2px 12px; }
.mt-zt-tile .k { grid-area: k; display: flex; align-items: center; gap: 7px; font-size: 12.5px; color: var(--mt-ink-3); }
.mt-zt-tile .v { grid-area: v; font-size: 26px; font-weight: 700; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
.mt-zt-tile .v small { font-size: 13px; font-weight: 500; color: var(--mt-ink-3); }
.mt-zt-tile .s { grid-area: s; font-size: 12px; color: var(--mt-ink-3); }
.mt-zt-spark { grid-area: sp; display: flex; gap: 4px; align-items: flex-end; font: 10px var(--mt-mono); color: var(--mt-ink-3); }
.mt-zt-spark > span { display: flex; flex-direction: column; align-items: center; gap: 2px; }
.mt-zt-spark b { width: 11px; height: 30px; border-radius: 3px; background: var(--mt-subtle); position: relative; overflow: hidden; display: block; }
.mt-zt-spark i { position: absolute; left: 0; right: 0; bottom: 0; }
.mt-zt-spark i.s-done { background: var(--zt-done); } .mt-zt-spark i.s-notdone { background: var(--zt-notdone); } .mt-zt-spark i.s-info { background: var(--mt-info); } .mt-zt-spark i.s-manual { background: var(--mt-skip); }

.mt-zt-next { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 340px), 1fr)); gap: 8px; }
.mt-zt-next button { width: 100%; text-align: left; border: 1px solid var(--mt-line); border-radius: 12px; background: var(--mt-paper); padding: 10px 12px; display: grid; grid-template-columns: 22px minmax(0, 1fr); gap: 4px 8px; }
.mt-zt-next button:hover, .mt-zt-next button[aria-pressed="true"] { border-color: var(--mt-ink-3); }
.mt-zt-next .n { grid-row: span 3; width: 22px; height: 22px; border-radius: 99px; background: var(--mt-subtle); font: 600 11px var(--mt-mono); display: grid; place-items: center; }
.mt-zt-next .nm { font-weight: 600; font-size: 13.5px; line-height: 1.35; }
.mt-zt-next .why { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; font-size: 12px; color: var(--mt-ink-3); }
.mt-zt-next .sub { font-size: 12px; }

.mt-zt-toolbar { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.mt-zt-toolbar .mt-seg button { display: inline-flex; align-items: center; gap: 6px; }
.mt-zt-toolbar .mt-input { flex: 1 1 220px; }
.mt-zt-tog { display: inline-flex; align-items: center; gap: 6px; font-size: 13px; color: var(--mt-ink-2); white-space: nowrap; }
.mt-zt-linkbtn { background: none; border: 0; padding: 0; }
.mt-zt-fm { position: relative; }
.mt-zt-fm .mt-btn.on { border-color: var(--mt-ink-3); background: var(--mt-subtle); }
.mt-zt-fm .mt-btn b { font-weight: 500; color: var(--mt-ink-2); max-width: 180px; overflow: hidden; text-overflow: ellipsis; }
.mt-zt-fmenu { position: absolute; z-index: 30; top: calc(100% + 4px); left: 0; min-width: 190px; background: var(--mt-paper); border: 1px solid var(--mt-line); border-radius: 10px; box-shadow: var(--mt-shadow); padding: 6px; display: flex; flex-direction: column; }
.mt-zt-fmenu label { display: flex; align-items: center; gap: 8px; padding: 6px 8px; border-radius: 6px; font-size: 13px; cursor: pointer; }
.mt-zt-fmenu label:hover { background: var(--mt-subtle); }
.mt-zt-fmenu .mt-link { align-self: flex-start; margin: 4px 8px; background: none; border: 0; padding: 0; }

/* The table flows with the page: the page scrolls over it and its header sticks under the top bar. */
