  const area = pillar?.areas.find((a) => a.id === task.areaId)
  const deps = task.dependencies.map((d) => plan.byId.get(d)).filter((d): d is Task => !!d)
  const after = dependentsOf(plan, task)
  const checks = orderedChecks(task)
