// What a run is about, for the report's title, top bar and footer. A run that connected to Microsoft Graph is about
// its tenant; a run that connected only to Active Directory is about its domain; a run of local tests is about
// neither, and the report names no subject rather than a placeholder.

import type { Model, Raw } from "./model"

// 3.0 writes "TenantName (not connected to Graph)" and the like when Graph is not connected. They are not names.
const PLACEHOLDER = /\(not connected to [^)]*\)\s*$/i

export function scrubPlaceholders(result: Raw): Raw {
  if (!result || typeof result !== "object") return result
  const out = { ...result }
  for (const key of ["TenantName", "TenantId", "Account"]) if (typeof out[key] === "string" && PLACEHOLDER.test(out[key])) out[key] = null
  return out
}

export type Subject = { name: string; kind: "tenant" | "domain" } | null

export function runSubject(result: Raw): Subject {
  const tenant = typeof result?.TenantName === "string" ? result.TenantName.trim().replace(/\.+$/, "") : ""
  if (tenant) return { name: tenant, kind: "tenant" }
  // Connect-Maester records Active Directory as "corp.contoso.com (dc01.corp.contoso.com)".
  const ad = (Array.isArray(result?.ConnectionSummary) ? result.ConnectionSummary : [])
    .find((c: Raw) => c?.Service === "Active Directory" && c?.Status === "Connected" && c?.Details)
  const domain = ad ? String(ad.Details).replace(/\s*\(.*\)\s*$/, "").trim() : ""
  if (domain) return { name: domain, kind: "domain" }
  return null
}

// TEMPORARY, for review: three wordings for the title of a run without a subject. A review copy of a report sets
// window.__mtTitleVariant to "a", "b" or "c"; the chosen one stays and the others go before this merges.
export type TitleVariant = "a" | "b" | "c"
export function titleVariant(): TitleVariant {
  const v = (globalThis as { __mtTitleVariant?: string }).__mtTitleVariant
  return v === "b" || v === "c" ? v : "a"
}

/** The suites a run's tests came from, as a name: one suite's ID, or how many. */
function suiteLabel(model: Model): string {
  const suites = [...new Set(model.rows.map((t) => (t.Package ? String(t.Package.Name || t.Package.Id) : t.Suite || t.Source || "Custom")))]
  if (suites.length === 1) return suites[0] === "Custom" ? "Custom tests" : suites[0]
  return `${suites.length} test suites`
}

/** Whether any test that ran ships with Maester, which makes the report a security report. */
const hasBuiltIn = (model: Model) => model.rows.some((t) => t.Source && t.Source !== "Custom" && !t.Package)

export interface Heading {
  /** Above the title, before the date. */
  eyebrow: string
  /** The title, given the pass rate. */
  title: (rate: number) => string
  /** The name in the top bar, or null for none. */
  bar: string | null
  /** What the footer says the report holds data from. */
  holds: string
}

export function reportHeading(model: Model): Heading {
  const subject = model.subject
  const v = titleVariant()
  const kind = hasBuiltIn(model) ? "Security report" : "Test report"
  const holds = subject ? subject.name : "the systems its tests read"
  if (subject) return {
    eyebrow: v === "a" ? "Maester report" : kind,
    title: (rate) => `${subject.name} passed ${rate}% of the checks that ran`,
    bar: subject.name,
    holds,
  }
  if (v === "b") return {
    eyebrow: kind,
    title: (rate) => `This run passed ${rate}% of the checks that ran`,
    bar: typeof model.result?.SystemInfo?.MachineName === "string" ? model.result.SystemInfo.MachineName : null,
    holds,
  }
  if (v === "c") {
    const suite = suiteLabel(model)
    return { eyebrow: "Maester report", title: (rate) => `${suite} passed ${rate}% of the checks that ran`, bar: suite, holds }
  }
  return { eyebrow: "Maester report", title: (rate) => `${rate}% of the checks that ran passed`, bar: null, holds }
}

